S = [('Inhalt', [('Teil 3: *Vorlesung 3* – Bewegung in *zwei und drei Dimensionen*', 'Willkommen zu Teil drei. In Vorlesung drei verlassen wir die gerade Linie: Jetzt bewegt sich etwas in der Ebene oder im Raum.'), ('Fahrplan: 3D-Grundlagen → *Wurf* → *Kreisbewegung* → *Bezugssysteme*', 'Der Fahrplan: erst Ort, Geschwindigkeit und Beschleunigung in drei Dimensionen, dann der schiefe Wurf, dann die Kreisbewegung und am Ende bewegte Bezugssysteme.')]), ('Verschiebung in drei Dimensionen', [('Im Raum: *drei Koordinaten* x, y, z → Ortsvektor *r*', 'Im Raum braucht man zu jedem Zeitpunkt drei Koordinaten: x, y und z. Zusammen bilden sie den Ortsvektor r. Er zeigt vom Ursprung zum Teilchen.'), ('Spitze von r über die Zeit = *Bahnkurve*', 'Die Spitze dieses Pfeils zeichnet während der Bewegung eine Linie in den Raum. Diese Linie heißt Bahnkurve.'), ('Später: neuer Ortsvektor r_2 → Verschiebung *Δr = r_2 − r_1*', 'Etwas später ist das Teilchen an einer anderen Stelle, mit dem Ortsvektor r zwei. Der rote Pfeil dazwischen ist die Verschiebung: Delta r gleich r zwei minus r eins.'), ('Komponentenweise: *Δx, Δy, Δz* – jede Achse für sich', 'Komponentenweise heißt das: Man zieht x von x ab, y von y und z von z. Heraus kommen die drei Verschiebungen Delta x, Delta y und Delta z.'), ('Beispiel: r_1 = (1; 2; 0) m, r_2 = (4; 6; 0) m → *Δr = (3; 4; 0) m*, Betrag *5 m*', 'Ein Zahlenbeispiel: r eins ist eins, zwei, null Meter, r zwei ist vier, sechs, null Meter. Dann ist Delta r gleich drei, vier, null Meter. Der Betrag ist die Wurzel aus neun plus sechzehn, also fünf Meter.')]), ('3D = drei 1D-Bewegungen', [('3D-Bewegung = *drei unabhängige 1D-Bewegungen*', 'Der wichtigste Gedanke dieser Vorlesung steht hier: Eine Bewegung im Raum ist nichts anderes als drei unabhängige, eindimensionale Bewegungen, die gleichzeitig ablaufen.'), ('Alles aus Vorlesung 1 gilt weiter – *pro Achse*', 'Alles, was du in Vorlesung eins für die x-Achse gelernt hast, gilt also weiter. Du wendest es nur auf jede Achse einzeln an.')]), ('Geschwindigkeit in 3D', [('1D: *v_x = ẋ* – Ableitung von x nach t', 'In einer Dimension war die Geschwindigkeit die Ableitung des Ortes nach der Zeit. Der Punkt über dem x ist die Kurzschreibweise für diese Zeitableitung.'), ('3D: *v = ṙ = ẋ e_x + ẏ e_y + ż e_z*', 'Im Raum machst du genau das für jede Komponente: x punkt, y punkt und z punkt. Das ist der Geschwindigkeitsvektor.'), ('Beispiel r(t) = (2t; 3t²; 0) m → v(t) = (2; *6t*; 0) m/s', 'Ein Beispiel: x gleich zwei t und y gleich drei t Quadrat. Abgeleitet: x punkt ist zwei, y punkt ist sechs t. Bei t gleich eins ist die Geschwindigkeit also zwei, sechs, null Meter pro Sekunde.')]), ('Beschleunigung in 3D', [('*a = dv/dt = d²r/dt²* – Ableitung der Geschwindigkeit', 'Die Beschleunigung ist wieder komponentenweise die Ableitung der Geschwindigkeit, also die zweite Ableitung des Ortes. Zwei Punkte bedeuten zweimal ableiten.'), ('Beispiel: v(t) = (2; 6t; 0) m/s → *a = (0; 6; 0) m/s²*', 'Im Beispiel von eben: Zwei abgeleitet ist null, sechs t abgeleitet ist sechs. Die Beschleunigung ist also null, sechs, null Meter pro Sekunde Quadrat. Sie ist konstant und zeigt nur in y-Richtung.')]), ('Der schiefe Wurf: Ausgangslage', [('Wurf: Start im *Ursprung*, r_0 = 0', 'Jetzt der wichtigste Anwendungsfall: der Wurf ohne Luftwiderstand, zum Beispiel ein Ball. Er startet im Ursprung, der Ortsvektor am Anfang ist also null.'), ('Beschleunigung: nur *a = −g e_y* – nach unten', 'Die einzige Beschleunigung ist die Erdbeschleunigung g, und die zeigt nur nach unten. Daher das Minuszeichen vor e y.'), ('Abwurf: *v_0* unter dem Winkel *φ*', 'Der Ball wird mit der Anfangsgeschwindigkeit v null unter dem Winkel phi abgeworfen.'), ('Zerlegen: *v_{0x} = v_0 cos φ* · *v_{0y} = v_0 sin φ*', 'Wie in Vorlesung zwei zerlegt man sie in zwei Komponenten: waagerecht v null mal Kosinus phi, senkrecht v null mal Sinus phi.'), ('Folienbild: v_0 ≈ 10 m/s, φ ≈ 86° → Gipfel *5,1 m*, Landung bei *1,4 m*', 'Die Kurve auf der Folie passt zu einem Ball, der mit etwa zehn Metern pro Sekunde fast senkrecht geworfen wird, mit etwa sechsundachtzig Grad. Er steigt fünf Komma eins Meter hoch und landet nach eins Komma vier Metern.')]), ('Was passiert beim Wurf?', [('x-Richtung: *keine Beschleunigung* → v_x bleibt konstant', 'Weil die Beschleunigung keine x-Komponente hat, ändert sich die waagerechte Geschwindigkeit nie. Der Ball wandert gleichmäßig nach rechts.'), ('y-Richtung: v_y nach oben, a nach unten → *erst bremsen, dann fallen*', 'In y-Richtung zeigen Geschwindigkeit und Beschleunigung in verschiedene Richtungen. Der Ball wird also erst abgebremst, bleibt im Gipfel kurz stehen und fällt dann zurück.'), ('Animation: v_x bleibt, *v_y* nimmt um 9,81 m/s pro Sekunde ab', 'Schau auf die Animation. Der grüne Pfeil, die waagerechte Geschwindigkeit, ist hier sehr klein und bleibt gleich. Der blaue Pfeil, die senkrechte Geschwindigkeit, wird jede Sekunde um neun Komma acht eins Meter pro Sekunde kleiner und dreht im Gipfel um.'), ('Im Gipfel: *v_y = 0* – nur v_x ist übrig', 'Im Gipfel ist die senkrechte Geschwindigkeit genau null. Diese Bedingung brauchen wir gleich, um die Gipfelhöhe zu berechnen.')]), ('Wurf: Bewegungsgleichungen', [('Kein neues Prinzip: *zweimal integrieren* – je Achse', 'Jetzt wird gerechnet. Wichtig: Hier kommt kein neues physikalisches Prinzip dazu. Wir integrieren die Beschleunigung zweimal, wie bei der geradlinigen Bewegung, nur eben für x und y getrennt.'), ('x: a_x = 0 → *ẋ = v_0 cos φ* (konstant)', 'In x-Richtung ist die Beschleunigung null. Integriert ergibt das: Die Geschwindigkeit bleibt beim Startwert v null mal Kosinus phi.'), ('→ *x = (v_0 cos φ) · t* – linear in t', 'Nochmal integriert: x gleich v null Kosinus phi mal t. Der Weg wächst also gleichmäßig mit der Zeit.'), ('y: a_y = −g → *ẏ = v_0 sin φ − g t*', 'In y-Richtung ist die Beschleunigung minus g. Integriert: Die Geschwindigkeit startet bei v null Sinus phi und nimmt pro Sekunde um g ab.'), ('→ *y = (v_0 sin φ) t − ½ g t²* – quadratisch in t', 'Nochmal integriert: y gleich v null Sinus phi mal t minus ein halb g t Quadrat. Das ist genau die Formel vom senkrechten Wurf aus Vorlesung eins.'), ('Zusammen: *r = x e_x + y e_y*', 'Beide Komponenten zusammen ergeben den Ortsvektor. Damit ist die Bewegung vollständig beschrieben.')]), ('Die Bahnkurve ist eine Parabel', [('Bahnkurve: *t eliminieren* – x-Gleichung nach t auflösen', 'Warum ist die Bahn eine Parabel? Dazu löst man die x-Gleichung nach t auf und setzt das Ergebnis in die y-Gleichung ein.'), ('t = x / (v_0 cos φ) → in y einsetzen', 'Aus x gleich v null Kosinus phi mal t folgt: t gleich x durch v null Kosinus phi.'), ('*y = tan φ · x − g x² / (2 v_0² cos² φ)* → Parabel', 'Eingesetzt erhältst du: y gleich Tangens phi mal x, minus g mal x Quadrat durch zwei v null Quadrat Kosinus Quadrat phi. Das ist eine nach unten offene Parabel in x.'), ('Gipfel: ẏ = 0 → *t_H = v_0 sin φ / g* · *H = v_0² sin² φ / (2g)*', 'Daraus folgen die wichtigen Kurzformeln. Im Gipfel ist y punkt null. Das ergibt die Steigzeit v null Sinus phi durch g. Eingesetzt in y erhältst du die Gipfelhöhe: v null Quadrat Sinus Quadrat phi durch zwei g.'), ('Landung: y = 0 → *T = 2 t_H* · Weite *W = v_0² sin(2φ) / g*', 'Gelandet ist der Ball, wenn y wieder null ist. Das passiert nach der doppelten Steigzeit. Setzt du diese Zeit in x ein, bekommst du die Wurfweite: v null Quadrat mal Sinus von zwei phi durch g.'), ('Beispiel v_0 = 20 m/s, φ = 45°: H = *10,2 m*, W = *40,8 m*', 'Ein Beispiel: v null zwanzig Meter pro Sekunde, Winkel fünfundvierzig Grad. Gipfelhöhe: vierhundert mal ein halb durch neunzehn Komma sechs zwei, das sind zehn Komma zwei Meter. Wurfweite: vierhundert mal Sinus neunzig Grad durch neun Komma acht eins, also vierzig Komma acht Meter. Bei fünfundvierzig Grad ist die Weite am größten, weil Sinus neunzig Grad gleich eins ist.')]), ('Kreisbewegung: Winkelposition', [('Kreisbewegung: Spitze von r läuft auf einem *Kreis* mit Radius r', 'Die zweite wichtige ebene Bewegung ist die Kreisbewegung, zum Beispiel ein Auto in einer Kurve mit festem Radius. Die Spitze des Ortsvektors läuft dabei auf einem Kreis.'), ('r konstant → nur der *Winkel φ(t)* ändert sich', 'Weil der Radius konstant ist, reicht eine einzige Angabe: der Winkel phi. Kennst du phi als Funktion der Zeit, kennst du die ganze Bewegung.'), ('x = r cos φ · y = r sin φ', 'Die Koordinaten sind dann x gleich r Kosinus phi und y gleich r Sinus phi.'), ('Bogenmaß: *φ = s / r* – Einheit *rad*', 'Der Winkel wird im Bogenmaß angegeben: Bogenlänge s geteilt durch den Radius. Die Einheit ist Radiant.'), ('Beispiel: s = r → φ = *1 rad ≈ 57,3°* · Vollkreis 2π rad = 360°', 'Zum Beispiel: Ist der Bogen genau so lang wie der Radius, ist phi gleich ein Radiant, das sind etwa siebenundfünfzig Komma drei Grad. Ein voller Kreis hat zwei pi Radiant, also dreihundertsechzig Grad.')]), ('Winkelgeschwindigkeit und -beschleunigung', [('Verdrehung *Δφ = φ_2 − φ_1*', 'Das Teilchen ist erst beim Winkel phi eins und kurz danach bei phi zwei. Es hat sich also um Delta phi gedreht.'), ('*ω = dφ/dt* – Winkelgeschwindigkeit in rad/s', 'Die Winkelgeschwindigkeit omega ist die Ableitung des Winkels nach der Zeit. Sie sagt, wie viele Radiant pro Sekunde überstrichen werden.'), ('*α = dω/dt = d²φ/dt²* – Winkelbeschleunigung in rad/s²', 'Die Winkelbeschleunigung alpha ist die zweite Ableitung. Sie sagt, wie schnell sich omega ändert.'), ('Merke: φ, ω, α ↔ *x, v, a* aus Vorlesung 1', 'Merke dir die Analogie: phi, omega und alpha verhalten sich wie x, v und a bei der geradlinigen Bewegung. Alle Formeln von dort gelten mit diesen Buchstaben weiter.')]), ('Der radiale Einheitsvektor', [('*e_r = r / r* – zeigt vom Mittelpunkt nach außen', 'Für die Kreisbewegung ist ein neuer Einheitsvektor praktisch: e r. Man bekommt ihn, indem man den Ortsvektor durch seine Länge teilt. Er zeigt immer vom Mittelpunkt nach außen.'), ('Damit: *r = r · e_r* – ganz einfach', 'Der Ortsvektor ist dann einfach Radius mal e r.'), ('Aber: e_r *dreht sich mit* – seine Richtung ändert sich ständig', 'Der Haken: e r dreht sich mit dem Teilchen mit. Seine Länge bleibt eins, aber seine Richtung ändert sich ständig. Deshalb ist seine Ableitung nicht null.')]), ('Wie ändert sich e_r?', [('Spitzen von e_r liegen auf einem Kreis mit *Radius 1*', 'Schauen wir, wie sich e r ändert. Die Spitzen von e r zu zwei Zeitpunkten liegen auf einem Kreis mit dem Radius eins.'), ('Bogen auf dem Einheitskreis = *Δφ*', 'Der Bogen dazwischen ist auf dem Einheitskreis genau so lang wie die Winkeländerung Delta phi.'), ('Δe_r / Δφ → Richtung der *Tangente* = *e_{φ}*', 'Teilt man die Änderung von e r durch Delta phi und lässt Delta phi gegen null gehen, zeigt das Ergebnis tangential. Diesen tangentialen Einheitsvektor nennt man e phi.')]), ('Wie ändert sich e_φ?', [('Genauso für e_{φ}: Änderung zeigt *nach innen*', 'Mit e phi macht man dasselbe. Seine Änderung zeigt aber nicht tangential, sondern zum Mittelpunkt hin, also genau gegen e r.'), ('Merke: *de_r/dφ = e_{φ}* · *de_{φ}/dφ = −e_r*', 'Merke dir die beiden Ergebnisse: e r abgeleitet nach phi ergibt e phi. e phi abgeleitet nach phi ergibt minus e r.')]), ('Zeitableitung der Einheitsvektoren', [('Kettenregel: *de_r/dt = (dφ/dt) · e_{φ} = ω e_{φ}*', 'Wir brauchen aber die Ableitung nach der Zeit. Mit der Kettenregel multipliziert man einfach mit phi punkt, also mit omega: e r punkt gleich omega mal e phi.'), ('Genauso: *de_{φ}/dt = −ω e_r*', 'Genauso gilt: e phi punkt gleich minus omega mal e r.')]), ('Geschwindigkeit auf dem Kreis', [('v = ṙ = r · ė_r = *r ω e_{φ}* (r konstant)', 'Jetzt ist die Geschwindigkeit ganz einfach. Der Radius ist konstant, also leitet man nur e r ab: v gleich r mal omega mal e phi.'), ('Richtung: *tangential* · Betrag: *v = r ω*', 'Die Geschwindigkeit zeigt also immer tangential, und ihr Betrag ist r mal omega.'), ('Beispiel: Rad r = 0,3 m, ω = 10 rad/s → v = *3 m/s*', 'Ein Beispiel: Ein Rad mit dreißig Zentimetern Radius dreht sich mit zehn Radiant pro Sekunde. Der Rand bewegt sich dann mit null Komma drei mal zehn, also drei Metern pro Sekunde.')]), ('Beschleunigung auf dem Kreis', [('a = dv/dt: *Produktregel*, weil ω und e_{φ} sich ändern', 'Für die Beschleunigung leitet man v ab. Hier ändern sich sowohl omega als auch e phi, deshalb braucht man die Produktregel.'), ('*a = r α e_{φ} − r ω² e_r*', 'Heraus kommen zwei Teile: r mal alpha in tangentialer Richtung und minus r mal omega Quadrat in radialer Richtung.'), ('Tangential *a_{φ} = r α* · radial *a_r = r ω² = v²/r*', 'Der tangentiale Teil a phi gleich r alpha ändert den Betrag der Geschwindigkeit. Der radiale Teil a r gleich r omega Quadrat ändert die Richtung. Wegen v gleich r omega kann man ihn auch als v Quadrat durch r schreiben.')]), ('Zentripetalbeschleunigung', [('Radialer Anteil = *Zentripetalbeschleunigung* – nach innen', 'Der radiale Anteil heißt Zentripetalbeschleunigung. Zentripetal heißt: zum Zentrum hin. Das steckt im Minuszeichen vor e r, denn e r zeigt ja nach außen.'), ('Ohne Zentripetalbeschleunigung *keine Kurve*', 'Ohne diese Beschleunigung würde der Körper geradeaus weiterfliegen. In der Kurve muss also immer eine Kraft nach innen wirken, beim Auto die Reibung der Reifen.')]), ('Gleichförmige Kreisbewegung', [('Gleichförmig: *ω konstant* → α = 0', 'Ein wichtiger Spezialfall ist die gleichförmige Kreisbewegung: omega ist konstant, also ist alpha null. Beispiele sind ein Satellit oder ein Auto, das gleichmäßig durch eine Kurve fährt.'), ('Ein Umlauf in T: *ω = 2π / T* · *v = 2π r / T*', 'Ein Umlauf dauert die Zeit T. Dabei werden zwei pi Radiant überstrichen. Also ist omega gleich zwei pi durch T und die Bahngeschwindigkeit zwei pi r durch T.'), ('*a_r = v² / r* – konstant, immer *nach innen*', 'Die Beschleunigung ist rein radial, zeigt immer nach innen und hat den konstanten Betrag v Quadrat durch r.'), ('Beispiel Kurve r = 50 m, v = 72 km/h = 20 m/s → a_r = *8 m/s²*', 'Ein Beispiel aus dem Straßenbau: Kurvenradius fünfzig Meter, Geschwindigkeit zweiundsiebzig Kilometer pro Stunde, das sind zwanzig Meter pro Sekunde. Die Zentripetalbeschleunigung ist vierhundert durch fünfzig, also acht Meter pro Sekunde Quadrat. Das ist fast so viel wie die Erdbeschleunigung.')]), ('Beschleunigt trotz gleichem Tempo', [('Tempo konstant – trotzdem *beschleunigt*', 'Merke dir diesen Satz für die Klausur: Obwohl der Betrag der Geschwindigkeit konstant ist, ist die gleichförmige Kreisbewegung eine beschleunigte Bewegung.'), ('Grund: Die *Richtung* von v ändert sich ständig', 'Der Grund ist die Richtung. Sie ändert sich ständig, und jede Änderung des Geschwindigkeitsvektors ist eine Beschleunigung.')]), ('Bezugssysteme: Zug und Bahnsteig', [('Ball im Zug: *Bahnsteig sieht etwas anderes*', 'Zum Schluss die Bezugssysteme. Wirft jemand im fahrenden Zug einen Ball senkrecht hoch, sieht der Mitfahrer eine gerade Linie. Vom Bahnsteig aus sieht man dagegen eine Wurfparabel.'), ('Beobachter *A* (Bahnsteig), Beobachterin *B* (Zug), Teilchen *P*', 'Beobachter A steht am Bahnsteig, Beobachterin B sitzt im Zug. Beide schauen auf dasselbe Teilchen P.'), ('Doppelindex: *r_{PA}* = Ort von P *aus Sicht von A*', 'Der Doppelindex wird so gelesen: r P A ist der Ort von P relativ zu A.')]), ('Galilei-Transformation herleiten', [('B fährt mit *v_{BA}* konstant → r_{BA} = v_{BA} t', 'B bewegt sich relativ zu A mit der konstanten Geschwindigkeit v B A. Starten beide am selben Ort, ist B nach der Zeit t bei v B A mal t.'), ('Vektoraddition: *r_{PA} = v_{BA} t + r_{PB}*', 'Nach der Regel der Vektoraddition gilt: Der Ort von P aus Sicht von A ist der Weg von A nach B plus der Ort von P aus Sicht von B.'), ('Ableiten: *v_{PA} = v_{BA} + v_{PB}*', 'Einmal nach der Zeit abgeleitet: Die Geschwindigkeiten addieren sich einfach.'), ('Nochmal: *a_{PA} = a_{PB}* – weil v_{BA} konstant', 'Und nochmal abgeleitet: Die Beschleunigungen sind gleich, weil die Ableitung der konstanten Relativgeschwindigkeit null ist.')]), ('Galilei-Transformation', [('Beide messen *dieselbe Beschleunigung*', 'Das wichtige Ergebnis: Beide Beobachter messen dieselbe Beschleunigung. Im Zug und am Bahnsteig fällt der Ball also mit g.'), ('Diese Umrechnung heißt *Galilei-Transformation*', 'Diese Umrechnung heißt Galilei-Transformation. Die Geschwindigkeitsgleichung ist die klassische Addition der Geschwindigkeiten.'), ('Gilt nur für v ≪ *Lichtgeschwindigkeit*', 'Sie gilt, solange alle Geschwindigkeiten klein gegen die Lichtgeschwindigkeit sind. Im Bauwesen ist das immer erfüllt.'), ('Beispiel: Zug 30 m/s, Ball 5 m/s hoch → vom Bahnsteig *(30; 5) m/s*', 'Ein Beispiel: Der Zug fährt mit dreißig Metern pro Sekunde, der Ball wird im Zug mit fünf Metern pro Sekunde senkrecht hochgeworfen. Vom Bahnsteig aus hat er die Geschwindigkeit dreißig, fünf, mit dem Betrag von etwa dreißig Komma vier Metern pro Sekunde. Die Beschleunigung ist für beide minus g. Damit ist Vorlesung drei geschafft.')])]
